/**
 * Where a template's kit comes from, and the assets it carries: logos, governed media
 * collections, map styles and config values. `BrandKitProvider` exposes these through
 * `useBrandKit()`; they are exported for code outside a provider.
 *
 * Relative asset paths in a published brandkit.json (`assets/logos/…`) resolve against the kit's
 * `baseUrl`, else the directory of the URL the kit was fetched from.
 *
 * Pure and DOM-free, apart from `loadBrandKit`, which takes a `fetch`.
 */
import { isPlainObject, textOf } from '../utility/json.js';

const ABSOLUTE = /^https?:\/\//i;

/** Brand Kit's production location for published kits: `<base>/teams/<team>/kits/<kit>/brandkit.json`. */
export const BRAND_KIT_PUBLIC_BASE_URL = 'https://uhuu-brandkit.s3.eu-west-1.amazonaws.com/live';

/** The directory relative asset URLs resolve against: the kit's `baseUrl`, else `sourceUrl`'s. */
export function brandKitBaseUrl(brandKit, sourceUrl) {
  const own = isPlainObject(brandKit) ? textOf(brandKit.baseUrl) : undefined;
  if (own) return own.replace(/\/+$/, '');
  const source = textOf(sourceUrl);
  if (!source || !ABSOLUTE.test(source)) return undefined;
  try {
    return new URL('.', source).toString().replace(/\/+$/, '');
  } catch {
    return undefined;
  }
}

/** Absolute against `base` when relative; `undefined` for anything that is not a plain URL. */
export function resolveBrandKitUrl(value, base) {
  const url = textOf(value);
  if (!url || /\s/.test(url)) return undefined;
  if (ABSOLUTE.test(url) || /^data:/i.test(url)) return url;
  if (/^[a-z][a-z0-9+.-]*:/i.test(url) || url.startsWith('//')) return undefined;
  if (!base) return url;
  try {
    return new URL(url, `${base}/`).toString();
  } catch {
    return undefined;
  }
}

const KIT_ID = /^kit-[\w-]+$/i;

/**
 * The brandkit.json URL a payload points at: `brandKitUrl` (absolute, relative to the template, or
 * a bare `kit-…` id), else `brandKitId`, else the embedded kit's `storage.publicUrl`. Ids resolve
 * under `publicBaseUrl` (default: Brand Kit production) and `brandKitTeamId` / `teamId`. `null`
 * when there is none: render the payload's `brandKit` or the bundled default.
 *
 * @param {object|null|undefined} payload
 * @param {{ publicBaseUrl?: string, teamId?: string|number }} [options]
 */
export function brandKitSourceUrl(payload, options = {}) {
  if (!isPlainObject(payload)) return null;
  const base = (textOf(options.publicBaseUrl) ?? BRAND_KIT_PUBLIC_BASE_URL).replace(/\/+$/, '');
  const team = textOf(String(payload.brandKitTeamId ?? options.teamId ?? ''));
  const fromId = (id) => (team ? `${base}/teams/${encodeURIComponent(team)}/kits/${encodeURIComponent(id)}/brandkit.json` : null);

  const url = textOf(payload.brandKitUrl);
  if (url) return KIT_ID.test(url) ? fromId(url) : resolveBrandKitUrl(url) ?? null;
  const id = textOf(payload.brandKitId);
  if (id) return KIT_ID.test(id) ? fromId(id) : null;
  const stored = isPlainObject(payload.brandKit?.storage) ? textOf(payload.brandKit.storage.publicUrl) : undefined;
  return stored && ABSOLUTE.test(stored) ? stored : null;
}

/**
 * Fetches a brandkit.json. Rejects on a network error, a non-2xx response or a body that is not
 * a JSON object, so the caller can keep its fallback kit.
 *
 * @param {string} url
 * @param {{ fetch?: typeof fetch, signal?: AbortSignal }} [options]
 */
export async function loadBrandKit(url, options = {}) {
  const doFetch = options.fetch ?? globalThis.fetch;
  if (typeof doFetch !== 'function') throw new Error('loadBrandKit needs fetch');
  const response = await doFetch(url, { signal: options.signal, headers: { accept: 'application/json' } });
  if (!response.ok) throw new Error(`Brand kit ${url} answered ${response.status}`);
  const document = await response.json();
  if (!isPlainObject(document)) throw new Error(`Brand kit ${url} is not a JSON object`);
  return document;
}

// --- Logos ------------------------------------------------------------------------------------

const LOGO_KIND = { primary: 'primary', logo: 'primary', lockup: 'primary', mark: 'mark', icon: 'mark', symbol: 'mark', wordmark: 'wordmark' };
const LEGACY_SLOT = { primary: 'logo', mark: 'icon' };
const ASSIGNMENT = { primary: 'logo.primary', mark: 'logo.icon' };

const fileOf = (files) => (isPlainObject(files) ? textOf(files.svg) ?? textOf(files.png) : undefined);

/**
 * A logo from the kit, resolved to an absolute `src`.
 *
 * `kind` is `primary` (alias `logo`), `mark` (alias `icon`) or `wordmark`; `background` is the
 * surface it sits on, `light` (default) or `dark`. Brand Kit's `logoSystem` is read first: the
 * variant of that kind for that background, else one marked `any`, else the other background.
 * Kits without a logo system fall back to `logos.logo` / `logos.icon` (`{ light, dark }`), then to
 * `logos[assignments['logo.primary']]` and `assets.primary` in template-bundled kits. `wordmark`
 * falls back to `primary`. Returns `null` when the kit has none.
 *
 * @param {object|null|undefined} brandKit
 * @param {{ kind?: string, background?: 'light'|'dark', sourceUrl?: string }} [options]
 * @returns {{ src: string, alt?: string, kind: string, background?: string, minWidth?: object, clearSpace?: object } | null}
 */
export function brandKitLogo(brandKit, options = {}) {
  if (!isPlainObject(brandKit)) return null;
  const kind = LOGO_KIND[String(options.kind ?? 'primary').toLowerCase()] ?? 'primary';
  const background = options.background === 'dark' ? 'dark' : 'light';
  const base = brandKitBaseUrl(brandKit, options.sourceUrl);
  const alt = textOf(brandKit.name);
  // Only a logo system names a wordmark; elsewhere it is the primary lockup.
  const found = logoFromSystem(brandKit, kind, background, base, alt) ?? (kind === 'wordmark' ? null : logoFromLegacy(brandKit, kind, background, base, alt));
  if (found || kind !== 'wordmark') return found;
  return brandKitLogo(brandKit, { ...options, kind: 'primary' });
}

function logoFromSystem(brandKit, kind, background, base, alt) {
  const variants = Array.isArray(brandKit.logoSystem?.variants) ? brandKit.logoSystem.variants.filter(isPlainObject) : [];
  const ofKind = variants.filter((variant) => variant.kind === kind && fileOf(variant.files));
  const variant =
    ofKind.find((item) => item.background === background) ??
    ofKind.find((item) => item.background === 'any') ??
    ofKind[0];
  if (!variant) return null;
  const src = resolveBrandKitUrl(fileOf(variant.files), base);
  if (!src) return null;
  return {
    src,
    alt: textOf(variant.name) ?? alt,
    kind,
    background: variant.background,
    ...(isPlainObject(variant.minWidth) ? { minWidth: variant.minWidth } : {}),
    ...(isPlainObject(variant.clearSpace) ? { clearSpace: variant.clearSpace } : {}),
  };
}

function logoFromLegacy(brandKit, kind, background, base, alt) {
  const logos = isPlainObject(brandKit.logos) ? brandKit.logos : {};
  const slot = logos[LEGACY_SLOT[kind]];
  if (isPlainObject(slot)) {
    const other = background === 'dark' ? 'light' : 'dark';
    for (const mode of [background, other]) {
      const value = slot[mode];
      const src = resolveBrandKitUrl(isPlainObject(value) ? value.src ?? value.url : value, base);
      if (src) return { src, alt: textOf(slot.alt) ?? alt, kind, background: mode };
    }
  }
  const assigned = textOf(brandKit.assignments?.[ASSIGNMENT[kind]]);
  const legacy = (assigned && logos[assigned]) || brandKit.assets?.[kind === 'mark' ? 'icon' : 'primary'];
  if (isPlainObject(legacy)) {
    const src = resolveBrandKitUrl(legacy.src ?? legacy.url, base);
    if (src) return { src, alt: textOf(legacy.alt) ?? textOf(legacy.name) ?? alt, kind };
  }
  return null;
}

// --- Collections ------------------------------------------------------------------------------

const COLLECTION_TYPE = { photos: 'photo', icons: 'icon', graphics: 'graphic', backgrounds: 'background', templates: 'template' };

/**
 * The media collection assigned to `kind` (`photos`, `icons`, `graphics`, `backgrounds`,
 * `templates`): `assignments['media.<kind>']`, else the first collection of that type. Items come
 * from the promoted version (`defaultVersionId`, or `versionId` when given), in the collection's
 * key order, each with an absolute `src` and its `key`. Template-bundled kits with a flat
 * `items` array are read too. `null` when the kit has none.
 *
 * @param {object|null|undefined} brandKit
 * @param {string} kind
 * @param {{ sourceUrl?: string, versionId?: string }} [options]
 */
export function brandKitCollection(brandKit, kind, options = {}) {
  if (!isPlainObject(brandKit) || !isPlainObject(brandKit.collections)) return null;
  const collections = brandKit.collections;
  const type = COLLECTION_TYPE[kind] ?? kind;
  const assigned = textOf(brandKit.assignments?.[`media.${kind}`]);
  const id =
    (assigned && isPlainObject(collections[assigned]) ? assigned : undefined) ??
    Object.keys(collections).find((key) => isPlainObject(collections[key]) && collections[key].type === type);
  if (!id) return null;

  const collection = collections[id];
  const base = brandKitBaseUrl(brandKit, options.sourceUrl);
  const versions = isPlainObject(collection.versions) ? collection.versions : {};
  const versionId = [textOf(options.versionId), textOf(collection.defaultVersionId)].find((key) => key && isPlainObject(versions[key]));
  const version = versionId ? versions[versionId] : undefined;
  const schemaKeys = isPlainObject(collection.schema?.keys) ? collection.schema.keys : {};

  let entries = [];
  if (version && isPlainObject(version.items)) {
    const keys = [...Object.keys(schemaKeys).filter((key) => key in version.items), ...Object.keys(version.items).filter((key) => !(key in schemaKeys))];
    entries = keys.map((key) => [key, version.items[key]]);
  } else if (Array.isArray(collection.items)) {
    entries = collection.items.map((item, index) => [String(isPlainObject(item) && textOf(item.key) ? item.key : index), item]);
  }

  const items = entries.flatMap(([key, item]) => {
    if (!isPlainObject(item)) return [];
    const src = resolveBrandKitUrl(item.src ?? item.url, base);
    if (!src) return [];
    const label = textOf(item.label) ?? textOf(schemaKeys[key]?.label) ?? textOf(item.name);
    return [{ ...item, key, src, ...(label ? { label } : {}) }];
  });

  return {
    id,
    name: textOf(collection.name),
    type: textOf(collection.type),
    versionId: versionId ?? undefined,
    items,
  };
}

// --- Config -----------------------------------------------------------------------------------

const envKey = (value) => (typeof value === 'string' ? value.trim().toUpperCase().replace(/[^A-Z0-9]+/g, '_') : '');

/**
 * A non-secret value from the kit's `config.env` rows. Keys compare case- and
 * punctuation-insensitively (`map-style-url` finds `MAP_STYLE_URL`); the first of `keys` present wins.
 *
 * @param {object|null|undefined} brandKit
 * @param {string|string[]} keys
 */
export function brandKitEnv(brandKit, keys) {
  const rows = Array.isArray(brandKit?.config?.env) ? brandKit.config.env : [];
  for (const wanted of (Array.isArray(keys) ? keys : [keys]).map(envKey)) {
    const row = rows.find((item) => isPlainObject(item) && envKey(item.key) === wanted && textOf(item.value));
    if (row) return row.value.trim();
  }
  return undefined;
}

/**
 * The map style for `mode` (`micro` or `macro`): `config.maps.styles[mode]`, else a
 * `MAP_<MODE>_STYLE_URL` / `MAP_STYLE_URL` env row. `null` when the kit sets none.
 *
 * @returns {{ url: string, name?: string, source: 'config.maps'|'config.env' } | null}
 */
export function brandKitMapStyle(brandKit, mode) {
  const which = mode === 'macro' ? 'macro' : 'micro';
  const style = brandKit?.config?.maps?.styles?.[which];
  const url = isPlainObject(style) ? textOf(style.url) : undefined;
  if (url) return { url, ...(textOf(style.name) ? { name: textOf(style.name) } : {}), source: 'config.maps' };
  const prefix = which.toUpperCase();
  const fromEnv = brandKitEnv(brandKit, [`MAP_${prefix}_STYLE_URL`, `MAP_STYLE_${prefix}_URL`, `${prefix}_MAP_STYLE_URL`, 'MAP_STYLE_URL']);
  return fromEnv ? { url: fromEnv, source: 'config.env' } : null;
}
