// The type a page inherits from the document, for a page drawn inside the shell's chrome (a
// thumbnail in the add and reorder sheets). A chrome root starts from the shell's own type
// (uhuu-editor-reset.css), so a page rendered there would take the shell's font, size and colour
// instead of the ones it is authored against. These are the properties that rule sets: keep the
// two lists the same.
export const CHROME_TYPOGRAPHY = [
  'font-family',
  'font-size',
  'font-weight',
  'font-style',
  'font-variant',
  'font-stretch',
  'font-feature-settings',
  'font-variation-settings',
  'line-height',
  'letter-spacing',
  'word-spacing',
  'text-transform',
  'text-indent',
  'text-align',
  'text-shadow',
  'color',
];

const camel = (property) => property.replace(/-([a-z])/g, (_, letter) => letter.toUpperCase());

/**
 * Inline style with the document's type, read where pages inherit it: the interactive scope that
 * wraps them, else <body>. `undefined` without a DOM (SSR).
 */
export function readDocumentTypography(doc = typeof document === 'undefined' ? undefined : document) {
  const source = doc?.querySelector('[data-uhuu-interactive]') ?? doc?.body;
  const computed = source ? doc.defaultView?.getComputedStyle(source) : undefined;
  if (!computed) return undefined;
  const style = {};
  for (const property of CHROME_TYPOGRAPHY) {
    const value = computed.getPropertyValue(property);
    if (value) style[camel(property)] = value;
  }
  return style;
}
