import React, { useEffect, useLayoutEffect, useState } from 'react';
import DocumentUtils from './pagination/DocumentUtils';
import PageSizeUtils from '../utility/PageSizeUtils';
import ConfigProvider from '../config/config-provider';
import { paginationReadiness } from './pagination-readiness';
import './pagination/print.css';
import './pagination/pagination-static.css';
import './../styles/uhuu-indicators.css';

interface PaginationProps {
  children: React.ReactNode;
  className?: string;
  setup: any;
}

/**
 * True inside PageEditor, whose readiness scope already covers the Pagination roots it renders
 * (and tracks their flow pages). Internal.
 */
export const PaginationReadinessOwnerContext = React.createContext(false);

const useIsoLayoutEffect = typeof window === 'undefined' ? useEffect : useLayoutEffect;

/**
 * A standalone Static.Pagination publishes `data-uhuu-pagination` with nothing to wait for, so a
 * renderer can tell a document that implements the contract from one that predates it. Same
 * lifecycle as PageEditor's scope: committed on layout, invalidated while Suspense hides it,
 * disposed on unmount.
 */
function useStandaloneReadiness(standalone: boolean) {
  const [scope] = useState(() => (standalone ? paginationReadiness.createScope() : null));
  useIsoLayoutEffect(() => {
    scope?.commit([], {});
    return () => scope?.suspend();
  }, [scope]);
  useEffect(() => () => scope?.unmount(), [scope]);
}

export const Pagination: React.FC<PaginationProps> = ({ children, className, setup }) => {
  const config = PageSizeUtils.pageParams("static", setup);
  useStandaloneReadiness(!React.useContext(PaginationReadinessOwnerContext));

  useEffect(() => {
    const styleLink = DocumentUtils.setupPageStyles(config?.page?.printCssUrl);

    return () => {
      if (styleLink) {
        DocumentUtils.removePageStyles(styleLink as HTMLLinkElement);
      }
    };
  }, [setup, config?.page?.printCssUrl]);

  const combinedClassName = ['uhuu-pagination', className, config?.page?.preview].filter(Boolean).join(' ');

  return (
    <ConfigProvider config={config}>
      <div className={combinedClassName}>
        {children}
      </div>
    </ConfigProvider>
  );
};

export default Pagination;
